<script setup lang="ts">
import { computed, ref } from 'vue';
import { ElMessage } from 'element-plus';
import {invoke,isTauri} from '@tauri-apps/api/core';
import { ArrowUp,ArrowDown,Cpu,MemoryStick,Download,Upload,HardDrive,Check } from 'lucide-vue-next';
import { preferences,savePreferences,defaultTrayPreferences,type TrayMetric,type TrayPreferences } from '../preferences';
import { monitorSnapshot } from '../monitor';
const saving=ref(false);
const settings=computed(()=>preferences.tray);
const metrics=[{id:'cpu',label:'CPU',icon:Cpu},{id:'memory',label:'内存',icon:MemoryStick},{id:'download',label:'下载速度',icon:Download},{id:'upload',label:'上传速度',icon:Upload},{id:'disk',label:'磁盘可用',icon:HardDrive}] as const;
const ordered=computed(()=>[...settings.value.metrics,...metrics.map(m=>m.id).filter(id=>!settings.value.metrics.includes(id))].map(id=>metrics.find(metric=>metric.id===id)!));
const interfaces=computed(()=>[...new Set([...(monitorSnapshot.value?.network_interfaces||[]),...(settings.value.network_interface==='auto'?[]:[settings.value.network_interface])])]);
const preview=computed(()=>settings.value.metrics.map(metric=>({cpu:settings.value.labeled?'CPU 18%':'C 18%',memory:settings.value.labeled?'内存 42%':'M 42%',download:settings.value.rate_unit==='bits'?'↓8.4Mb':'↓1.0M',upload:settings.value.rate_unit==='bits'?'↑128Kb':'↑16K',disk:settings.value.labeled?'可用 128G':'D 128G'})[metric]).join('  '));
async function change(patch:Partial<TrayPreferences>){if(saving.value)return;saving.value=true;try{await savePreferences(current=>({tray:{...current.tray,...patch}}));}catch(error){ElMessage.error(String(error));}finally{saving.value=false;}}
function toggleMetric(metric:TrayMetric){const values=settings.value.metrics.includes(metric)?settings.value.metrics.filter(id=>id!==metric):[...settings.value.metrics,metric];if(!values.length&&!settings.value.show_icon){ElMessage.warning('请至少保留图标或一个指标');return;}void change({metrics:values});}
function move(metric:TrayMetric,direction:number){const values=[...settings.value.metrics],index=values.indexOf(metric),target=index+direction;if(index<0||target<0||target>=values.length)return;[values[index],values[target]]=[values[target]!,values[index]!];void change({metrics:values});}
function checked(event:Event){return (event.target as HTMLInputElement).checked;}
function value(event:Event){return (event.target as HTMLSelectElement).value;}
async function previewPanel(){try{await invoke('show_tray_panel');}catch(error){ElMessage.error(String(error));}}
</script>
<template>
  <div class="tray-settings" :aria-busy="saving">
    <div class="setting-preview"><span>菜单栏预览 <small>示例数据</small></span><div><svg v-if="settings.show_icon" viewBox="0 0 44 44" width="18" height="18" aria-hidden="true"><path d="M29 10a15 15 0 1 0 2 23" fill="none" stroke="currentColor" stroke-width="5.5" stroke-linecap="round"/><path d="M33 11c1 7 2 8 8 9-6 1-7 2-8 9-1-7-2-8-8-9 6-1 7-2 8-9Z" fill="currentColor"/></svg><b>{{ preview || '仅显示图标' }}</b></div><button v-if="isTauri()" class="preview-button" :disabled="!settings.enabled||saving" @click="previewPanel">打开面板 ↗</button></div>
    <label class="setting-row"><span>启用菜单栏<small>关闭后可在本机监控中重新开启</small></span><input type="checkbox" role="switch" :checked="settings.enabled" :disabled="saving" @change="change({enabled:checked($event)})"/></label>
    <div class="settings-section"><div class="section-heading"><b>显示哪些指标</b><div class="presets"><button :disabled="saving" @click="change({metrics:['download','upload']})">网速</button><button :disabled="saving" @click="change({metrics:['cpu','memory']})">资源</button><button :disabled="saving" @click="change({metrics:['cpu','memory','download','upload']})">组合</button></div></div>
      <div v-for="metric in ordered" :key="metric.id" class="metric-setting"><button class="metric-check" :aria-pressed="settings.metrics.includes(metric.id)" :disabled="saving" @click="toggleMetric(metric.id)"><span class="check-box" :class="{selected:settings.metrics.includes(metric.id)}"><Check v-if="settings.metrics.includes(metric.id)" :size="11"/></span><component :is="metric.icon" :size="14"/><span>{{ metric.label }}</span></button><div v-if="settings.metrics.includes(metric.id)" class="order-buttons"><button :aria-label="`前移${metric.label}`" :disabled="saving||settings.metrics.indexOf(metric.id)===0" @click="move(metric.id,-1)"><ArrowUp :size="12"/></button><button :aria-label="`后移${metric.label}`" :disabled="saving||settings.metrics.indexOf(metric.id)===settings.metrics.length-1" @click="move(metric.id,1)"><ArrowDown :size="12"/></button></div></div>
    </div>
    <label class="setting-row"><span>显示应用图标</span><input type="checkbox" role="switch" :checked="settings.show_icon" :disabled="saving||!settings.metrics.length" @change="change({show_icon:checked($event)})"/></label>
    <label class="setting-row"><span>完整标签<small>关闭时用 C / M 缩写节省空间</small></span><input type="checkbox" role="switch" :checked="settings.labeled" :disabled="saving" @change="change({labeled:checked($event)})"/></label>
    <label class="setting-row"><span>刷新频率</span><select :value="settings.interval_ms" :disabled="saving" @change="change({interval_ms:Number(value($event))})"><option :value="1000">每 1 秒</option><option :value="2000">每 2 秒</option><option :value="3000">每 3 秒</option><option :value="5000">每 5 秒 · 省电</option></select></label>
    <label class="setting-row"><span>网速单位</span><select :value="settings.rate_unit" :disabled="saving" @change="change({rate_unit:value($event) as 'bytes'|'bits'})"><option value="bytes">字节 / 秒 · MB/s</option><option value="bits">比特 / 秒 · Mb/s</option></select></label>
    <label class="setting-row"><span>统计网卡<small>自动模式合计物理网卡，排除隧道</small></span><select :value="settings.network_interface" :disabled="saving" @change="change({network_interface:value($event)})"><option value="auto">自动 · Wi-Fi / 以太网</option><option v-for="name in interfaces" :key="name" :value="name">{{ name }}</option></select></label>
    <label class="setting-row"><span>面板趋势图</span><input type="checkbox" role="switch" :checked="settings.show_sparklines" :disabled="saving" @change="change({show_sparklines:checked($event)})"/></label>
    <label class="setting-row"><span>关闭窗口后留在菜单栏<small>可从面板或右键菜单退出应用</small></span><input type="checkbox" role="switch" :checked="settings.close_to_tray" :disabled="saving" @change="change({close_to_tray:checked($event)})"/></label>
    <button class="reset-settings" :disabled="saving" @click="change(defaultTrayPreferences())">恢复默认设置</button>
  </div>
</template>
<style scoped>
.tray-settings{font-size:12px;color:var(--text);text-align:left}.setting-preview{padding:14px;border-radius:13px;background:var(--accent-soft);border:1px solid var(--accent-border);margin-bottom:8px}.setting-preview>span{display:flex;justify-content:space-between;color:var(--text-muted);font-size:10px}.setting-preview small{font-size:9px;color:var(--text-faint)}.setting-preview>div{display:flex;align-items:center;gap:9px;min-height:26px;margin-top:8px}.setting-preview b{font-family:ui-monospace,SFMono-Regular,monospace;font-size:11px;font-weight:500;white-space:pre-wrap;overflow-wrap:anywhere}.setting-row{display:flex;justify-content:space-between;align-items:center;gap:12px;min-height:48px;padding:9px 1px;border-bottom:1px solid var(--line)}.setting-row>span{line-height:1.5}.setting-row small{display:block;font-size:10px;color:var(--text-faint);margin-top:3px}.setting-row select{max-width:165px;min-width:90px;border:1px solid var(--line);border-radius:7px;padding:6px 8px;background:var(--surface);color:var(--text-secondary);font-size:10px;text-overflow:ellipsis}.setting-row input{appearance:none;width:29px;height:17px;flex-shrink:0;background:var(--border-strong);border-radius:99px;position:relative;cursor:pointer;margin:0}.setting-row input:after{content:'';position:absolute;width:13px;height:13px;top:2px;left:2px;background:white;border-radius:50%;transition:transform .15s}.setting-row input:checked{background:var(--accent-strong)}.setting-row input:checked:after{transform:translateX(12px)}.setting-row input:disabled{opacity:.45;cursor:default}.settings-section{padding:15px 0 8px;border-bottom:1px solid var(--line)}.section-heading{display:flex;justify-content:space-between;align-items:center;margin-bottom:8px}.section-heading b{font-size:11px;font-weight:500}.presets{display:flex;gap:4px}.presets button{border:0;background:var(--surface-subtle);color:var(--text-muted);font-size:10px;padding:4px 7px;border-radius:5px;cursor:pointer}.presets button:hover{color:var(--accent);background:var(--accent-soft)}.metric-setting{display:flex;align-items:center;justify-content:space-between;height:34px}.metric-check{display:flex;align-items:center;gap:9px;border:0;background:none;color:var(--text-secondary);font-size:11px;padding:5px 0;cursor:pointer}.metric-check>svg{color:var(--text-faint)}.check-box{width:15px;height:15px;border:1px solid var(--border-strong);border-radius:4px;display:grid;place-items:center}.check-box.selected{background:var(--accent-strong);border-color:var(--accent-strong);color:white}.order-buttons{display:flex;gap:3px}.order-buttons button{width:23px;height:23px;border:0;border-radius:5px;background:var(--surface-subtle);color:var(--text-muted);display:grid;place-items:center;cursor:pointer}.order-buttons button:disabled{opacity:.25;cursor:default}.reset-settings{display:block;border:0;background:none;color:var(--text-faint);font-size:10px;margin:15px auto 0;cursor:pointer}.reset-settings:hover{color:var(--accent)}
.preview-button{border:0;background:none;color:var(--accent);font-size:10px;cursor:pointer;padding:7px 0 0}.preview-button:disabled{opacity:.4;cursor:default}
</style>
